using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval — GetTypeInfo returns JsonTypeInfo which you cast
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// 2) Probe without throwing: TryGetTypeInfo returns false when the resolver
//    cannot produce metadata for the requested type.
//    Here we use a resolver that resolves nothing (always returns null).
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new NullResolver()
};

bool found = limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? maybeInfo);
Console.WriteLine($"TryGetTypeInfo on empty resolver — found? {found}, value: {(maybeInfo is null ? "null" : maybeInfo.Type.Name)}");

// Contrast: TryGetTypeInfo succeeds with the real resolver
bool found2 = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info2);
Console.WriteLine($"TryGetTypeInfo on real resolver  — found? {found2}, value: {(info2 is null ? "null" : info2.Type.Name)}");

public record Person(string Name, int Age);

// A resolver that always returns null (knows about no types)
file class NullResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
}
